<script setup lang="ts">
import{computed,onMounted,reactive,ref}from'vue';import{actualizarCliente,eliminarCliente,listarClientes,registrarCliente,type Cliente,type Option,type Payload}from'../services/clientes'
const rows=ref<Cliente[]>([]),types=ref<Option[]>([]),criterion=ref(''),loading=ref(false),saving=ref(false),modal=ref(false),editing=ref<Cliente|null>(null),error=ref(''),success=ref(''),total=ref(0),page=ref(1),lastPage=ref(1);const empty=():Payload=>({tipo_documento_id:0,documento:'',nombres:'',apellido_paterno:'',apellido_materno:'',celular:'',correo:'',fecha_nacimiento:'',sexo:'m'}),form=reactive<Payload>(empty());const selectedType=computed(()=>types.value.find(x=>x.id===form.tipo_documento_id));const isCompany=computed(()=>selectedType.value?.nombre.toLowerCase().includes('ruc')||selectedType.value?.longitud===11)
async function load(p=1){loading.value=true;error.value='';page.value=p;try{const r=await listarClientes(criterion.value,p);rows.value=r.data;total.value=r.total;lastPage.value=r.last_page;types.value=r.tipos_documento}catch(e){error.value=msg(e)}finally{loading.value=false}}function open(x?:Cliente){editing.value=x||null;Object.assign(form,x?{tipo_documento_id:x.tipo_documento_id,documento:x.documento,nombres:x.nombres,apellido_paterno:x.apellido_paterno||'',apellido_materno:x.apellido_materno||'',celular:x.celular||'',correo:x.correo||'',fecha_nacimiento:x.fecha_nacimiento,sexo:x.sexo}:empty());modal.value=true;error.value=''}function validate(){if(!form.tipo_documento_id||!form.documento||!form.nombres||!form.fecha_nacimiento)return'Complete los campos obligatorios.';const length=selectedType.value?.longitud;if(length&&form.documento.length!==length)return`El documento debe tener ${length} dígitos.`;if(!isCompany.value&&(!form.apellido_paterno||!form.apellido_materno))return'Complete los apellidos del propietario.';if(form.correo&&!/^\S+@\S+\.\S+$/.test(form.correo))return'Ingrese un correo electrónico válido.';return''}async function save(){const issue=validate();if(issue){error.value=issue;return}saving.value=true;error.value='';try{if(editing.value){await actualizarCliente(editing.value.id,{...form});success.value='Cliente actualizado correctamente.'}else{await registrarCliente({...form});success.value='Cliente registrado correctamente.'}modal.value=false;await load(editing.value?page.value:1)}catch(e){error.value=msg(e)}finally{saving.value=false}}async function remove(x:Cliente){if(x.predios_count){error.value=`No se puede eliminar a ${x.nombre_completo} porque tiene ${x.predios_count} predio(s) asociado(s).`;return}if(!confirm(`¿Eliminar a ${x.nombre_completo}?`))return;try{await eliminarCliente(x.id);success.value='Cliente eliminado correctamente.';await load(page.value)}catch(e){error.value=msg(e)}}function msg(e:unknown){return e instanceof Error?e.message:'No se pudo completar la operación.'}onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / EVAN / Catastro / Clientes</nav><header class="hero"><div class="mark">CL</div><div><small>EVAN · CATASTRO COMERCIAL</small><h1>Padrón de clientes</h1><p>Administración de propietarios naturales y jurídicos vinculables a predios.</p></div><div class="counter"><b>{{total}}</b><span>clientes registrados</span></div><button @click="open()">+ Nuevo cliente</button></header><p v-if="success" class="flash good">✓ {{success}}</p><p v-if="error" class="flash bad">{{error}}</p><section class="search"><label>Buscar propietario<input v-model.trim="criterion" placeholder="Nombres, apellidos o documento" @keyup.enter="load(1)"></label><button @click="load(1)">Buscar</button></section><div v-if="loading" class="empty">Cargando clientes…</div><div v-else-if="!rows.length" class="empty">No se encontraron clientes.</div><section v-else class="table"><header><span>Cliente</span><span>Documento</span><span>Contacto</span><span>Predios</span><span>Acciones</span></header><article v-for="x in rows" :key="x.id"><div class="person"><i>{{x.tipo_documento.toLowerCase().includes('ruc')?'PJ':'PN'}}</i><div><b>{{x.nombre_completo}}</b><small>{{x.sexo==='f'?'Femenino':'Masculino'}} · Nac. {{x.fecha_nacimiento}}</small></div></div><div><b>{{x.tipo_documento}}</b><span>{{x.documento}}</span></div><div><b>{{x.celular||'Sin celular'}}</b><span>{{x.correo||'Sin correo'}}</span></div><div><strong>{{x.predios_count}}</strong><span>predio(s)</span></div><div class="actions"><button @click="open(x)">Editar</button><button class="delete" :disabled="x.predios_count>0" :title="x.predios_count?'Tiene predios asociados':''" @click="remove(x)">Eliminar</button></div></article></section><footer v-if="lastPage>1" class="pages"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>{{page}} / {{lastPage}}</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></footer>
<div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="modal" @submit.prevent="save"><header><div><small>{{editing?'ACTUALIZACIÓN':'NUEVO REGISTRO'}}</small><h2>{{editing?'Editar cliente':'Registrar cliente'}}</h2></div><button type="button" @click="modal=false">×</button></header><section class="grid"><label>Tipo de documento *<select v-model.number="form.tipo_documento_id"><option :value="0">Seleccione</option><option v-for="x in types" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Número de documento *<input v-model.trim="form.documento" inputmode="numeric" :maxlength="selectedType?.longitud||20"></label><label :class="{wide:isCompany}">{{isCompany?'Razón social':'Nombres'}} *<input v-model.trim="form.nombres"></label><template v-if="!isCompany"><label>Apellido paterno *<input v-model.trim="form.apellido_paterno"></label><label>Apellido materno *<input v-model.trim="form.apellido_materno"></label><label>Sexo *<select v-model="form.sexo"><option value="m">Masculino</option><option value="f">Femenino</option></select></label></template><label>Fecha de nacimiento / constitución *<input v-model="form.fecha_nacimiento" type="date"></label><label>Celular<input v-model.trim="form.celular" inputmode="numeric"></label><label>Correo electrónico<input v-model.trim="form.correo" type="email"></label></section><footer><button type="button" class="clear" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':editing?'Guardar cambios':'Registrar cliente'}}</button></footer></form></div></div></template>
<style scoped>
