ons button:disabled{opacity:.35}.empty{margin-top:12px;padding:45px;text-align:center;background:#fff;font-size:.58rem}.pages{display:flex;justify-content:center;align-items:center;gap:8px;font-size:.48rem}.backdrop{position:fixed;z-index:100;inset:0;padding:16px;display:grid;place-items:center;background:#14283888}.modal{width:min(100%,720px);max-height:94vh;overflow:auto;padding:20px;border-radius:12px;background:#fff}.modal>header{display:flex}.modal h2{margin:2px 0;font-size:.85rem}.modal>header>button{margin-left:auto;border:0;background:none;font-size:1.4rem}.grid{margin-top:12px;display:grid;grid-template-columns:1fr 1fr;gap:8px}.grid label{font-size:.47rem}.wide{grid-column:span 2}.modal footer{margin-top:14px;display:flex;justify-content:flex-end;gap:6px}.clear{color:#64737a!important;background:#edf1f2!important}@media(max-width:850px){.table>header{display:none}.table>article{grid-template-columns:1fr 1fr}}@media(max-width:540px){.hero{flex-wrap:wrap}.counter{margin-left:0}.search{align-items:stretch;flex-direction:column}.table>article,.grid{grid-template-columns:1fr}.wide{grid-column:auto}}
